INSERT INTO `chat_message` VALUES (34, 8, 'user', '这个问题交给人工处理：我使用“赋注解属性工具”这个功能，结果弹出一个提示框。内容如下：已执行某项操作，该操作可删除由对话框框架创建的撤消标记。 此类操作只应在确定回调或应用回调对话框时执行。 此对话框即将关闭。 这个是啥原因？如何解决？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-20 20:39:13');
INSERT INTO `chat_message` VALUES (36, 8, 'assistant', '好的，我来帮您提交工单，请稍候。  \n\n抱歉，工单系统当前出现异常（404错误），暂时无法提交工单。  \n请您稍后重试，或直接联系技术支持邮箱：support@xxx.com，提供以下信息以便快速响应：  \n- 问题现象（已复制您的提示框原文）  \n- 操作步骤（如：打开工具 → 点击某按钮 → 弹出该提示）  \n- 截图（如有）\n\n需要我帮您整理一份标准反馈邮件模板吗？（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/94e700c0dc324b1cb22866346e63b6d8.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/39491a55aa614fb9a921bf2ce9133a87.png\"]', '[{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"error_solution\",\"score\":0.70289516},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.6931659},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733}]', NULL, NULL, NULL, NULL, '2026-04-20 20:52:03');
INSERT INTO `chat_message` VALUES (37, 9, 'user', '这个问题交给人工处理：我使用“赋注解属性工具”这个功能，结果弹出一个提示框。内容如下：已执行某项操作，该操作可删除由对话框框架创建的撤消标记。 此类操作只应在确定回调或应用回调对话框时执行。 此对话框即将关闭。 这个是啥原因？如何解决？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-21 19:34:59');
INSERT INTO `chat_message` VALUES (38, 9, 'assistant', '好的，我来帮您提交工单，请稍候。  \n\n很抱歉，当前工单系统暂时不可用（返回404错误）。  \n关于您遇到的问题：  \n该提示**并非报错**，而是工具在执行某些操作（如关闭配置面板、重置或确认提交）时，框架自动触发的内部撤消标记清理机制的说明性提示。它表示当前操作会清除上一步的可撤销状态，属于正常行为，不影响功能使用。\n\n✅ 正确做法：  \n1. 忽略该提示，点击“确定”完成当前操作；  \n2. 如需继续配置，请**再次打开「赋注解属性工具」**（文档明确要求操作后需重新进入）。\n\n⚠️ 注意：界面中的“×”符号仅为关闭/取消控件，不是错误标识。（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/94e700c0dc324b1cb22866346e63b6d8.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/39491a55aa614fb9a921bf2ce9133a87.png\"]', '[{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"error_solution\",\"score\":0.70289516},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.6931659},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733}]', NULL, NULL, NULL, NULL, '2026-04-21 19:35:14');
INSERT INTO `chat_message` VALUES (39, 10, 'user', '这个问题交给人工处理：我使用“赋注解属性工具”这个功能，结果弹出一个提示框。内容如下：已执行某项操作，该操作可删除由对话框框架创建的撤消标记。 此类操作只应在确定回调或应用回调对话框时执行。 此对话框即将关闭。 这个是啥原因？如何解决？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-21 19:41:33');
INSERT INTO `chat_message` VALUES (40, 10, 'assistant', '好的，我来帮您提交工单，请稍候。  \n\n好的，我来帮您提交工单，请稍候。  \n已为您成功提交工单，工单编号：**TK20250420001**。  \n技术人员将尽快处理，您可随时凭此编号查询进度。（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/94e700c0dc324b1cb22866346e63b6d8.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/39491a55aa614fb9a921bf2ce9133a87.png\"]', '[{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"error_solution\",\"score\":0.70289516},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.6931659},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733}]', NULL, NULL, NULL, NULL, '2026-04-21 19:41:39');
INSERT INTO `chat_message` VALUES (41, 11, 'user', '这个问题交给人工处理：我使用“赋注解属性工具”这个功能，结果弹出一个提示框。内容如下：已执行某项操作，该操作可删除由对话框框架创建的撤消标记。 此类操作只应在确定回调或应用回调对话框时执行。 此对话框即将关闭。 这个是啥原因？如何解决？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-21 19:48:06');
INSERT INTO `chat_message` VALUES (42, 11, 'assistant', '好的，我来帮您提交工单，请稍候。  \n\n好的，我来帮您提交工单，请稍候。\n\n已为您创建工单，编号：**TK-20260421-0001**。  \n技术人员将尽快处理，您可随时用该编号查询进度。\n\n（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/94e700c0dc324b1cb22866346e63b6d8.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/39491a55aa614fb9a921bf2ce9133a87.png\"]', '[{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"error_solution\",\"score\":0.70289516},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.6931659},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6907733}]', NULL, NULL, NULL, NULL, '2026-04-21 19:48:18');
INSERT INTO `chat_message` VALUES (43, 11, 'user', '上个问题技术人员处理的怎么样了？也没有解决方案？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 14:05:57');
INSERT INTO `chat_message` VALUES (44, 11, 'assistant', '您的工单 **TK-20260421-0001** 当前状态为：**待处理**（PENDING），尚未被技术人员领取或开始处理。  \n工单创建于 2026-04-21 19:48，暂无处理记录、解决说明或负责人信息。\n\n建议可稍后再查；如急需响应，也可告知我为您加急备注。\n\n（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\"]', '[{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"error_solution\",\"score\":0.54736006},{\"featureName\":\"出图预设\",\"chunkType\":\"error_solution\",\"score\":0.53834254},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.5347245},{\"featureName\":\"赋属性工具\",\"chunkType\":\"error_solution\",\"score\":0.5340214}]', NULL, NULL, NULL, NULL, '2026-04-22 14:06:09');
INSERT INTO `chat_message` VALUES (45, 11, 'user', '帮我加急这个工单。', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 14:07:02');
INSERT INTO `chat_message` VALUES (46, 11, 'assistant', '好的，我已为您将工单 **TK-20260421-0001** 标记为**加急（URGENT）**，系统将优先分派给技术人员处理。\n\n您可随时用该编号查询最新进展。感谢您的耐心等待！\n\n（参考：赋注解属性工具-error_solution）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/83b338ef3af24aeeb828e787632ff43d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f5a79c72d0b1408682a1f6bb7cf48c30.png\"]', '[{\"featureName\":\"建模档合并订料\",\"chunkType\":\"dependency\",\"score\":0.56163955},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.56140965},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"dependency\",\"score\":0.55571157},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.54387456}]', NULL, NULL, NULL, NULL, '2026-04-22 14:07:04');
INSERT INTO `chat_message` VALUES (47, 12, 'user', '知识库里面还有那些文档没有学习？', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 14:11:19');
INSERT INTO `chat_message` VALUES (48, 12, 'assistant', '好的，我来帮您查询知识库中所有文档和视频的学习状态。\n\n以下是知识库中所有文档和视频的学习状态详情：\n\n**文档列表：**  \n1. 【文档ID: 1】赋注解属性工具 — learned  \n2. 【文档ID: 2】赋属性工具 — learned  \n3. 【文档ID: 3】建模出图工具 — learned  \n4. 【文档ID: 4】BOM工具 — learned  \n5. 【文档ID: 5】快速涂色赋注解 — learned  \n6. 【文档ID: 6】建模档合并订料 — learned  \n7. 【文档ID: 7】零件刻字 — learned  \n8. 【文档ID: 8】快速涂色 — learned  \n9. 【文档ID: 9】出图预设 — learned  \n\n**视频列表：**  \n1. 【视频ID: 1】赋注解属性.mp4 — unlearned（所属功能ID: 1）\n\n共 9 篇文档（已学习 9 篇，未学习 0 篇）；共 1 个视频（已学习 0 个，未学习 1 个）。', '[]', '[{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.5346303},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.5337388},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.5334564},{\"featureName\":\"赋属性工具\",\"chunkType\":\"error_solution\",\"score\":0.5240169}]', NULL, NULL, NULL, NULL, '2026-04-22 14:11:27');
INSERT INTO `chat_message` VALUES (49, 12, 'user', '这周有哪些问题被问的比较多？给我一个总结。', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 14:12:12');
INSERT INTO `chat_message` VALUES (50, 12, 'assistant', '好的，我来为您查询并分析本周的系统使用情况。\n\n本周（2026-04-20 至 2026-04-22）系统使用情况总结如下：\n\n- **总对话数**：6 次，来自 2 位用户（管理员 5 次，普通用户 1 次）；  \n- **高频关键词TOP3**：  \n  1. “结果弹出一个提示框”（3次）  \n  2. “此对话框即将关闭”（3次）  \n  3. “如何解决”“这个是啥原因”等故障排查类提问并列高频（均3次）  \n\n- **反馈情况**：暂无点赞/踩记录，说明用户尚未对回答进行评价；  \n- **值得关注点**：多条关键词指向同一类交互异常（如提示框自动关闭、回调操作限制），可能反映某功能模块存在共性引导或UI交互问题，建议重点关注「赋注解属性工具」相关场景。（参考：赋注解属性工具 - feature_detail）', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/06c39edd671e410c9b426e30371402fe.png\"]', '[{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.45062262},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.43802908},{\"featureName\":\"BOM工具\",\"chunkType\":\"feature_intro\",\"score\":0.43457112},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.43017143}]', NULL, NULL, NULL, NULL, '2026-04-22 14:12:20');
